        $scope.AnesthesiaEvaluation = function (obj, val) {
            if (val === "Yes") {
                if (obj.Value == "Yes") {
                    obj.Value = "";
                    obj.PatientPreviousAnestheticId = obj.PatientPreviousAnestheticId || null;
                    if (obj.PatientPreviousAnestheticId != null) {
                        obj.DeleteInd = "Y";
                    }
                } else if (obj.Value == "No" || obj.Value == "") {
                    obj.Value = "Yes";
                    obj.DeleteInd = "N";
                }

                let tempArray = $filter('filter')($scope.PrevAnestheticsObj.PreviousAnesthetics, { 'Value': "Yes" }, true);

                if (tempArray.length === $scope.PrevAnestheticsObj.PreviousAnesthetics.length) {
                    $scope.PrevAnestheticsObj.IsAllActionCheckListCheckedEvaluation = 1;
                } else {
                    $scope.PrevAnestheticsObj.IsAllActionCheckListCheckedEvaluation = null;
                }

            }

            if (val === "No") {
                if (obj.Value == "No") {
                    obj.Value = "";
                    obj.PatientPreviousAnestheticId = obj.PatientPreviousAnestheticId || null;
                    if (obj.PatientPreviousAnestheticId != null) {
                        obj.DeleteInd = "Y";
                    }
                } else if (obj.Value == "Yes" || obj.Value == "") {
                    obj.Value = "No";
                    obj.DeleteInd = "N";
                }
                let tempArray = $filter('filter')($scope.PrevAnestheticsObj.PreviousAnesthetics, { 'Value': "No" }, true);

                if (tempArray.length === $scope.PrevAnestheticsObj.PreviousAnesthetics.length) {
                    $scope.PrevAnestheticsObj.IsAllActionCheckListCheckedEvaluation = 2;
                } else {
                    $scope.PrevAnestheticsObj.IsAllActionCheckListCheckedEvaluation = null;
                }
            }
        };
