                    var oldparts = [];

                    if (psychislist[0].PsychisType) newparts.push('Psychis Type :' + psychislist[0].PsychisType);
                    if (logpsychislist[0].PsychisType) oldparts.push('Psychis Type :' + logpsychislist[0].PsychisType);
                    psychisData = newparts.join('\n ');
