                        if (reqObj.AnesthesiaPlan.AnesthetistNotes != '') {
                            Affected += `\nAnesthestic Plan Notes : ${reqObj.AnesthesiaPlan.AnesthetistNotes}`;
                        }
                        if ($scope.LogObj.AnesthetistNotes != '') {
                            OldAffected += `\nAnesthestic Plan Notes :  ${$scope.LogObj.AnesthetistNotes}`;
                        }
